"""Сводка для автора по статьям D11–D30: доля его текста, вопросы Д, что сверить. Пишет md, затем docx."""
import re, glob, sys, subprocess
TMP = sys.argv[1]
out = ["# Михаилу Юрьевичу: как читать статьи D11–D30", "",
"Здравствуйте, Михаил Юрьевич! Это 20 статей для сайта и бота, написанные от Вашего первого лица. Чтобы Вам не искать главное, ниже по каждой статье — что взято из Ваших записей, что дописала редакция и какие вопросы ждут Вашего решения.", "",
"**Как устроен файл статьи:**", "",
"- **чёрный текст** — Ваши слова из записей, расставленные по разделам (минимальная правка — только чтобы фраза читалась);",
"- **серый текст** — написан редакцией в Вашей манере по клиническим рекомендациям и международным руководствам. Он публикуется только после Вашего утверждения. Всё, с чем Вы не согласны, — правьте или вычёркивайте;",
"- **⚑** — утверждение, которое рецензент сверяет с источником;",
"- в конце — **таблица утверждений** и **список источников**.", "",
"**Просьба:** правьте в режиме рецензирования Word («Рецензирование → Исправления»), вопросы оставляйте примечаниями на полях. Так ни одна Ваша правка не потеряется.", "",
"**Что изменилось по сравнению с прошлой версией:** все статьи пересобраны — признаки «скорая сейчас» вынесены в начало, убраны повторы, частые вопросы сведены в один блок. Учтены Ваши правки к D03–D10: никаких домашних растворов, раствор комнатной температуры, рвоту дома не вызываем, 30 минут после прививки — обязательно, согласие — обязательное информированное добровольное, рефлюкс — через гастроэнтеролога.", ""]
rows = []; qs = []
for f in sorted(glob.glob('seo/articles/denisov/D*.md')):
    aid = f.split('/')[-1][:3]
    if not ('D11' <= aid <= 'D30'): continue
    t = open(f, encoding='utf-8').read()
    title = re.search(r'^title: (.+)$', t, re.M).group(1)
    rev = re.search(r'^reviewer: "?(.+?)"?$', t, re.M).group(1)
    body = t[t.index('\n# '):t.index('## Таблица утверждений')]
    grey = black = 0; g = False
    for ln in body.split('\n'):
        if ln.startswith('::: {custom'): g = True; continue
        if ln.strip() == ':::': g = False; continue
        n = len(ln.split())
        if g: grey += n
        else: black += n
    share = round(100 * black / max(1, grey + black))
    tab = t[t.index('## Таблица утверждений'):]
    flags = body.count('⚑')
    d = []
    for r in tab.split('\n'):
        c = [x.strip() for x in r.strip('|').split('|')]
        if len(c) >= 5 and c[0].isdigit() and ('Д' in c[4] or c[3] == '—' or 'автор' in c[4].lower()):
            d.append(f"{c[1]} — {c[4] or 'решение автора'}")
    rev = rev.replace(' (формулировки о согласии)','').replace('инструктор первой помощи / комбустиолог','инструктор первой помощи')
    rows.append(f"| {aid} | {title} | {share}% | {flags} | {len(d)} | {(rev.replace('[ФИО, должность]; + ','').replace('[ФИО, должность]','педиатр') if '+' not in rev else 'педиатр + ' + rev.split('+',1)[1].strip()).replace('|','/')} |")
    qs.append((aid, title, d))
out += ["## Сводка", "", "| № | статья | Ваш текст | пометок ⚑ | вопросов | рецензенты |", "|-------|------------------------------|----------|----------|----------|----------------|"] + rows + ["",
"«Ваш текст» — доля слов из Ваших записей. В D22–D30 записей по теме почти не было, поэтому там почти всё серое — эти статьи просим читать внимательнее всего.", "",
"## Вопросы, которые ждут Вашего решения", ""]
for aid, title, d in qs:
    out.append(f"### {aid}. {title}")
    out += [f"- {x}" for x in d] if d else ["- отдельных вопросов нет; просьба утвердить серый текст"]
    out.append("")
out += ["## Что редакция изменила в Ваших формулировках — просим подтвердить", "",
"- **D12 Ацетон.** Убрана фраза «не давать много сладкого до исключения диабета»: при ацетоне на фоне голода у ребёнка без диабета сладкое питьё как раз помогает, и прежняя формулировка могла задержать помощь. Теперь: сладкое питьё — по совету врача, когда диабет исключён; при первом эпизоде, жажде и частом мочеиспускании, диабете в семье — сначала врач и сахар крови. Подагра как причина в текст не включена. Нужен взгляд эндокринолога.",
"- **D21 Манту.** В записи — «оценивают через 24–48 часов» и «измеряют красноту». По методике оценивают через 72 часа и измеряют уплотнение (папулу), а не покраснение. В тексте исправлено, просим подтвердить.",
"- **D20 Календарь.** В записи среди болезней календаря названа ветряная оспа; в национальный календарь (приказ № 1122н) она не входит, её рекомендует календарь Союза педиатров. Из Вашей фразы ветряная оспа убрана и упомянута отдельно как дополнительная прививка. Формулировка «обязательное условие для всех детей» заменена на рекомендацию с обязательным добровольным согласием — юрист проверит.",
"- **D11 Отравление.** Совет «вызвать рвоту, нажав на корень языка» (ягоды на улице) не включён — он противоречит Вашей правке «рвоту дома не вызываем».",
"- **D14, D25 Сон.** Совет поднимать изголовье кроватки книжками не включён: руководства по безопасному сну (AAP 2022) считают наклонные поверхности опасными для младенцев.",
"- **D15 Запор.** Фраза «в кабачке и цветной капусте клетчатки нет» не включена — нужно сверить.",
"- **D16 Витамин D.** Дозы в единицах не приводим (правило проекта): «дозу назначает педиатр».",
"- **D17 Невролог.** «Массаж назначается абсолютно всем» смягчено до «курс массажа назначает врач».",
"- **D18 Анализы.** Сроки «в 6 месяцев и в 1 год» — сверить с новым приказом о профосмотрах № 211н (действует с 01.09.2025).", "",
"## Что проверила редакция", "",
"Через поиск сверены реквизиты ключевых источников: руководства AAP по желтухе (2022) и безопасному сну (2022), ориентиры развития CDC/AAP (2022), NICE NG240 по менингококковой инфекции (2024), протокол ABM № 36 по маститу (2022), рекомендация ERC 2021 охлаждать ожог 20 минут, приказ № 1122н. Найдено и исправлено: приказы № 124н и № 514н с 01.09.2025 заменены приказами № 190н и № 211н. Остальные пометки ⚑ проверяет рецензент — номера версий российских клинических рекомендаций указываются при сверке.", "",
"Спасибо! Если удобнее обсудить голосом — достаточно 10 минут по каждой статье с вопросами."]
md = TMP + '/brief.md'; open(md, 'w', encoding='utf-8').write('\n'.join(out).replace('⚑', '[*]'))
subprocess.run(['pandoc', md, '-o', 'seo/articles/denisov/docx/00-Для-Михаила-Юрьевича.docx'], check=True)
print('\n'.join(rows))
